/**
 * Библиотека Талантов — Warhammer DBC.
 *
 * Создаётся в компендиуме "warhammer-dbc.talents" при первом запуске
 * (см. warhammer-dbc.mjs, хук "ready"). Разбита по папкам = функциональным
 * группам. Заполнение неразрушающее (по имени) — существующее не трогается.
 *
 * Авто-эффекты (ядро): system.effects.{charBonusStat,charBonusValue,initMod,
 * fearRating}. Применяются в actor.mjs (prepareDerivedData) так же, как у Черт.
 * Большинство Талантов ситуативны/дают приёмы — их правила в description.
 *
 * Склонности (Скл.) = aptitudes, определяющие цену в ХР. Метки оригинала
 * (WS/BS/S/T/A/I/P/W/F/Inf + FC/Fin/Def/Off/Gen/Soc/Knw/Tec/Psi) маппятся
 * на ключи APTITUDES.
 */

const IMG = "icons/svg/upgrade.svg";

// Метки Скл. → ключи APTITUDES
const APT = {
  WS: "ws", BS: "bs", S: "s", T: "t", A: "ag", I: "int", P: "per", W: "wp",
  F: "fel", Inf: "inf", FC: "fieldcraft", Fin: "finesse", Def: "defence",
  Off: "offence", Gen: "general", Soc: "social", Knw: "knowledge",
  Tec: "tech", Psi: "psyker"
};
const apt = (s) => (s || "").split(",").map(x => x.trim()).filter(Boolean)
  .map(x => APT[x]).filter(Boolean);

const FX0 = { charBonusStat: "", charBonusValue: 0, initMod: 0, fearRating: 0 };
// Как и у Черт (см. traits-library.mjs) — единый bookSource для всего файла,
// точная страница по каждому Таланту не сверена.
const TALENT_BOOK = "DoomBC — Основная книга";

// name, tier, god, skills, req, desc, spec, fx
// Текст таланта кладётся в benefit — именно его выводит система раскрытия
// описаний («ЧТО ДАЁТ»). description оставляем пустым.
const T = (name, tier, god, skills, req, desc, spec = "", fx = null) => ({
  name, type: "talent", img: IMG,
  system: {
    description: "", notes: "", benefit: desc, tier, bookSource: TALENT_BOOK,
    requirement: req || "", aptitudes: apt(skills),
    god: god || "", specialization: spec || "",
    effects: { ...FX0, ...(fx || {}) }
  }
});

const group = (folder, arr) => arr.map(t => ({ ...t, folder }));
// Вложенная группа: папка folder внутри родительской папки parent.
const subgroup = (parent, folder, arr) => arr.map(t => ({ ...t, folder, folderParent: parent }));

